import{_ as d,C as n,o as c,c as l,a6 as i,E as a,j as s,a as t}from"./chunks/framework.5dd0l9Wo.js";const b=JSON.parse('{"title":"WebSockets","description":"The handshake that bypasses CORS, message-level trust, and cross-site WebSocket hijacking.","frontmatter":{"title":"WebSockets","description":"The handshake that bypasses CORS, message-level trust, and cross-site WebSocket hijacking."},"headers":[],"relativePath":"websockets/index.md","filePath":"websockets/index.md"}'),p={name:"websockets/index.md"};function h(u,e,g,m,w,v){const o=n("LabGroup"),r=n("TopicComplete");return c(),l("div",null,[e[0]||(e[0]=i('<h1 id="websockets-·-the-case-of-the-open-intercom" tabindex="-1">WebSockets · The Case of the Open Intercom <a class="header-anchor" href="#websockets-·-the-case-of-the-open-intercom" aria-label="Permalink to &quot;WebSockets · The Case of the Open Intercom&quot;">​</a></h1><p class="wd-section-lede">A WebSocket is a persistent, two-way communication channel between a browser and a server. While traditional HTTP requests are like sending individual letters back and forth, a WebSocket is an open telephone line. But here is the critical discovery: once a WebSocket is established, it completely bypasses the browser&#39;s Same-Origin Policy—making handshake authorization and message validation essential.</p><div class="wd-callout"><p><strong>💡 Everyday Analogy: The Open Intercom Line.</strong> Imagine an office intercom connecting your private desk directly to a storage room. Traditional HTTP is like sending written memos through mail inspection. A WebSocket, however, is a live intercom wire: once someone presses the buzzer and opens the line, both ends can speak instantly without further inspection. If you don&#39;t check who pressed the buzzer during the initial connection, an eavesdropper can dial in, listen to private conversations, and shout orders into the room.</p></div><h2 id="case-file-1-cross-site-websocket-hijacking-cswsh" tabindex="-1">Case File #1: Cross-Site WebSocket Hijacking (CSWSH) <a class="header-anchor" href="#case-file-1-cross-site-websocket-hijacking-cswsh" aria-label="Permalink to &quot;Case File #1: Cross-Site WebSocket Hijacking (CSWSH)&quot;">​</a></h2><p>Let&#39;s trace how an external site can tap into your live chat session.</p><div class="wd-case"><div class="wd-step wd-step--see"><span class="wd-step__tag">🔎 Step 1 · What You Notice in the Browser</span><p>You are logged into a customer service portal on <code>support.example</code> and chatting with a representative. Messages appear instantly in the chat window without page refreshes.</p></div><div class="wd-step wd-step--server"><span class="wd-step__tag">⚙️ Step 2 · What the Server Does Behind the Scenes</span><p>While that chat is open, you visit an attacker&#39;s website on <code>evil.example</code>. JavaScript on their page runs <code>new WebSocket(&#39;wss://support.example/chat&#39;)</code>. The browser initiates an HTTP Upgrade request, automatically attaching your valid session cookie:</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Browser Handshake Headers &amp; Valid Session</span><span><span class="wd-code-input">Gold</span> = Attacker&#39;s Origin Header</span></div><span class="wd-code-dev">GET /chat HTTP/1.1</span><br><span class="wd-code-dev">Host: support.example</span><br><span class="wd-code-dev">Upgrade: websocket</span><br><span class="wd-code-dev">Connection: Upgrade</span><br><span class="wd-code-dev">Cookie: session=9c4a8f10e7b23d</span><br><span class="wd-code-input">Origin: https://evil.example</span></div></div><div class="wd-step wd-step--break"><span class="wd-step__tag">💥 Step 3 · Where the Logic Breaks</span><p>The server sees a valid session cookie and answers <code>101 Switching Protocols</code>. Because the Same-Origin Policy does not restrict WebSocket connections, the server ignores the <code>Origin</code> header! The attacker&#39;s script now receives all real-time chat messages and can send messages in the victim&#39;s name.</p></div><div class="wd-step wd-step--fix"><span class="wd-step__tag">🛡️ Step 4 · How Developers Lock It Down</span><p>Developers strictly validate the <code>Origin</code> header against an approved domain allow-list during the handshake. Additionally, servers require a one-time, unpredictable connection token (like an anti-CSRF token) in the upgrade request to confirm intentional user authorization.</p></div></div><h3 id="visual-comparison-http-same-origin-policy-vs-unrestricted-websockets" tabindex="-1">Visual Comparison: HTTP Same-Origin Policy vs. Unrestricted WebSockets <a class="header-anchor" href="#visual-comparison-http-same-origin-policy-vs-unrestricted-websockets" aria-label="Permalink to &quot;Visual Comparison: HTTP Same-Origin Policy vs. Unrestricted WebSockets&quot;">​</a></h3><div class="wd-compare"><div class="wd-compare__card wd-compare__card--expect"><span class="wd-compare__title">💭 What the Developer Expected</span><p>The developer assumed that because standard HTTP requests require CORS headers to read data across origins, WebSockets would naturally provide the same cross-origin protections.</p></div><div class="wd-compare__card wd-compare__card--actual"><span class="wd-compare__title">💥 What Actually Happened</span><p>WebSockets are not constrained by CORS. Any website on the internet can establish a WebSocket connection to the server, and the browser will attach the user&#39;s session cookies automatically.</p></div></div><hr><h2 id="the-websocket-connection-lifecycle" tabindex="-1">The WebSocket Connection Lifecycle <a class="header-anchor" href="#the-websocket-connection-lifecycle" aria-label="Permalink to &quot;The WebSocket Connection Lifecycle&quot;">​</a></h2><p>From initial HTTP upgrade to continuous data frames, a WebSocket connection moves through five distinct checkpoints:</p><div class="wd-flow"><div class="wd-flow__node"><strong>1. Upgrade Handshake</strong> Client sends HTTP request with <code>Upgrade: websocket</code> and session cookie. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>2. Origin &amp; Auth Check</strong> Server validates <code>Origin</code> header and verifies session credentials. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--safe"><strong>3. 101 Switching Protocols</strong> Connection transitions from HTTP to a persistent TCP socket. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>4. Bi-Directional Frames</strong> Client and server exchange text or binary messages continuously. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>5. Message Validation</strong> Every incoming frame must be parsed, validated, and encoded. </div></div><details class="details custom-block"><summary>🔬 Under the Hood: Why WebSockets are Not Covered by CORS</summary><p>CORS exists to restrict <code>fetch()</code> and <code>XMLHttpRequest</code> responses inside the browser. When a browser initiates a WebSocket connection, it sends a standard HTTP handshake. However:</p><ol><li>The browser does not require the server to return <code>Access-Control-Allow-Origin</code> before establishing the socket.</li><li>Any <code>Access-Control-Allow-Origin</code> headers returned by the server are completely ignored by the WebSocket API.</li></ol><p>The <strong>only</strong> line of defense against cross-site connection hijacking is the server manually inspecting the <code>Origin</code> header during the handshake and dropping unauthorized connections.</p></details><hr><h2 id="message-level-trust-validating-every-frame" tabindex="-1">Message-Level Trust: Validating Every Frame <a class="header-anchor" href="#message-level-trust-validating-every-frame" aria-label="Permalink to &quot;Message-Level Trust: Validating Every Frame&quot;">​</a></h2><p>Opening a secure socket is only half the battle. Once connected, every message sent across the socket must be treated as untrusted user input:</p><ul><li><strong>Cross-Site Scripting (XSS):</strong> If a chat application broadcasts incoming WebSocket messages to other users without HTML entity encoding, an investigator can send an XSS payload through a socket frame to trigger stored XSS on all connected clients.</li><li><strong>Server-Side Injection:</strong> Just like HTTP parameters, messages sent over WebSockets can flow into database queries (SQLi) or system commands if not properly parameterized.</li></ul>',17)),a(o,{ids:"websockets-lab-manipulating-messages-to-exploit-vulnerabilities"}),e[1]||(e[1]=s("hr",null,null,-1)),e[2]||(e[2]=s("h2",{id:"handshake-header-manipulation",tabindex:"-1"},[t("Handshake Header Manipulation "),s("a",{class:"header-anchor",href:"#handshake-header-manipulation","aria-label":'Permalink to "Handshake Header Manipulation"'},"​")],-1)),e[3]||(e[3]=s("p",null,"The initial HTTP Upgrade handshake is subject to the same tampering as any regular web request:",-1)),e[4]||(e[4]=s("ul",null,[s("li",null,[s("strong",null,"IP-Based Restrictions:"),t(" If a server uses IP allow-lists or rate limits to protect its socket endpoint, spoofing headers like "),s("code",null,"X-Forwarded-For"),t(" may bypass those controls if reverse proxies are misconfigured.")]),s("li",null,[s("strong",null,"Session Replay:"),t(" If the WebSocket handshake does not bind the socket to the authenticated session state, replaying handshake parameters may grant unauthorized access.")])],-1)),a(o,{ids:"websockets-lab-manipulating-handshake-to-exploit-vulnerabilities"}),e[5]||(e[5]=i('<details class="details custom-block"><summary>⚙️ Architecture &amp; Server Quirks: How WebSockets Differ by Stack</summary><ul><li><strong>Nginx Reverse Proxying:</strong> Requires explicit configuration directives (<code>proxy_set_header Upgrade $http_upgrade</code> and <code>proxy_set_header Connection &quot;upgrade&quot;</code>). A misconfigured proxy may strip upgrade headers or mishandle connections.</li><li><strong>Node.js <code>ws</code> library:</strong> By default, <code>ws</code> does <strong>not</strong> verify the <code>Origin</code> header. Developers must explicitly implement the <code>verifyClient</code> callback.</li><li><strong>Socket.IO:</strong> Uses its own proprietary protocol on top of WebSockets and long-polling. It includes its own <code>cors: { origin: ... }</code> options which behave differently from raw WebSocket implementations.</li><li><strong>HTTP/2 &amp; HTTP/3:</strong> Traditional <code>Upgrade:</code> headers are forbidden in HTTP/2. Instead, RFC 8441 defines an extended <code>CONNECT</code> method for tunneling WebSockets over existing HTTP/2 streams.</li></ul></details><div class="wd-callout wd-callout--warn"><p><strong>🛡️ The Detective&#39;s Defense Blueprint.</strong> Always validate the <code>Origin</code> header against an explicit HTTPS allow-list during the handshake. Protect against CSWSH by generating a short-lived, single-use anti-CSRF ticket before opening the socket. Apply the same rigorous input validation and output encoding to WebSocket message frames as you would to standard REST API payloads.</p></div>',2)),a(r,{"topic-id":"websockets",label:"Mark WebSockets complete"})])}const S=d(p,[["render",h]]);export{b as __pageData,S as default};
